from Sundar:
fvalor <- function(alfa) {
   integrand <- function(tt, alfa) {
     tt/(alfa*(exp(tt)-1))
   }
   valor <- integrate(integrand,
                      lower = 0,
                      upper = alfa,
                      alfa = alfa)$integral
   return(valor)
}

